```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::notifier;

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let kept: Vec<&ItemVerdict> = composed.entries.iter().filter(|e| e.kept).collect();

        let mut message = format!(
            "Digest {}: {} item(s) kept\n",
            composed.date,
            kept.len()
        );
        for e in &kept {
            message.push_str(&format!("- {} <{}>\n", e.title, e.link));
        }

        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
